export function timeToPercent(datetime: string): number {
  const date = new Date(datetime);
  const minutes = date.getHours() * 60 + date.getMinutes();
  return (minutes / MINUTES_IN_DAY) * FULL_DAY_PERCENT;
}

/**
 * Day-view placement. A slot that finishes on a later day is drawn through
 * midnight so it stays on this axis. The stored start and end are unchanged.
 */
export function slotPosition(start: string, end: string) {
  const topPercent = Math.max(0, timeToPercent(start));
  const bottomPercent = endsOnLaterDay(start, end)
    ? FULL_DAY_PERCENT
    : Math.min(FULL_DAY_PERCENT, timeToPercent(end));

  return {
    top: `${topPercent}%`,
    height: `${bottomPercent - topPercent}%`,
  };
}

